import I18N from '@src/lang/I18N';
import { Button, Col, Image } from 'antd';
import { FC } from 'react';

import { checkAuth } from '@/layout/utills';
import { CarbonReductionPerms } from '@/router/utils/carbonReductionEnum';
import { CommonColumnsActionType } from '@/views/eca/util/actionType';
import { safeParseJson } from '@/views/eca/util/transJson';

import styles from './EnergyEfficiencyCard.module.less';
import { MeasuresPageListData } from '../type';

export const EnergyEfficiencyCardItem: FC<{
  item: MeasuresPageListData;
  handelCardClick: (
    actionType: CommonColumnsActionType,
    record: MeasuresPageListData,
  ) => void;
}> = ({ item, handelCardClick }) => {
  return (
    <Col span={8}>
      <div className={styles.card}>
        <Image
          preview={false}
          src={safeParseJson(item?.bannerUrl)?.[0]?.url}
          alt={item?.bannerUrl}
          className={styles.cardImage}
          fallback='data:image/png;base64,'
        />
        {/* 标签区域 1 高 红色；2 中 蓝色；3 低 绿色 */}
        <div className={styles[`initTag${item?.feasibilityType}`]}>
          {item?.feasibilityType_name}
        </div>
        {/* 预计减排量、预计年效益区域 */}
        <div className={styles.benefitContainer}>
          <div className={styles.benefitItem}>
            <div className={styles.benefitTitle}>
              {I18N.eca.expectedEmissionReduction}
            </div>
            <div className={styles.benefitValue}>
              <span>{item?.reductionAmount || '-'}</span>
              <span>{I18N.eca.tcOeYear}</span>
            </div>
          </div>
          <div className={styles.benefitItem}>
            <div className={styles.benefitTitle}>
              {I18N.eca.expectedAnnualBenefits2}
            </div>
            <div className={styles.benefitValue}>
              <span>{item?.expectRevenue || '-'}</span>
              <span>{I18N.eca.theKCNYYearOfAnEra}</span>
            </div>
          </div>
        </div>
        <div className={styles.cardContent}>
          <div className={styles.contentWrapper}>
            <h2 className={styles.title}>{item?.measureName}</h2>
            <div className={styles.detailsContainer}>
              <div className={styles.measure}>
                {I18N.eca.emissionReductionType}
                {item?.measureType_name}
              </div>
              <div className={styles.scope}>
                {I18N.eca.reach2}
                {item?.scopeTypes}
              </div>
              <div className={styles.cost}>
                {I18N.eca.estimatedCost2}
                {item?.estimatedCost || 0} {I18N.eca.KCNY}
              </div>
            </div>
          </div>
          <div className={styles.actionButtons}>
            {checkAuth(
              CarbonReductionPerms.measuresEdit,
              <Button
                className={styles.primaryButton}
                onClick={() => {
                  handelCardClick(CommonColumnsActionType.EDIT, item);
                }}
                type='default'
              >
                {I18N.Factors.edit}
              </Button>,
            )}
            {checkAuth(
              CarbonReductionPerms.measuresDelete,
              <Button
                className={styles.secondaryButton}
                onClick={() => {
                  handelCardClick(CommonColumnsActionType.DELETE, item);
                }}
                type='default'
              >
                {I18N.Factors.delete}
              </Button>,
            )}
            {checkAuth(
              CarbonReductionPerms.measuresShow,
              <Button
                className={styles.secondaryButton}
                onClick={() => {
                  handelCardClick(CommonColumnsActionType.SHOW, item);
                }}
                type='default'
              >
                {I18N.eca.details}
              </Button>,
            )}
          </div>
        </div>
      </div>
    </Col>
  );
};
